package com.slcm.portal.finance;

import com.slcm.portal.finance.FinanceDtos.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

@Service
public class FinanceService {
    private final FinanceAccess a; private final DocumentStorage files;
    FinanceService(FinanceAccess a, DocumentStorage files) { this.a=a; this.files=files; }
    private DocumentTypeView type(Map<String,Object> r) { return new DocumentTypeView(((Number)r.get("id")).longValue(),(String)r.get("code"),(String)r.get("name"),(String)r.get("description"),(Boolean)r.get("active")); }
    public List<DocumentTypeView> types(boolean all) { return a.db.queryForList("SELECT id,code,name,description,active FROM document_types "+(all?"ORDER BY name":"WHERE active=TRUE ORDER BY name")).stream().map(this::type).toList(); }
    @PreAuthorize("hasRole('ADMIN')") @Transactional public DocumentTypeView createType(DocumentTypeInput x) { long id=a.insert("INSERT INTO document_types(code,name,description,active) VALUES(?,?,?,?)",x.code(),x.name(),x.description(),x.active()); a.audit("CREATE","DOCUMENT_TYPE",id); return type(a.db.queryForMap("SELECT id,code,name,description,active FROM document_types WHERE id=?",id)); }
    @PreAuthorize("hasRole('ADMIN')") @Transactional public DocumentTypeView editType(long id, DocumentTypeInput x) { a.update("UPDATE document_types SET code=?,name=?,description=?,active=? WHERE id=?",x.code(),x.name(),x.description(),x.active(),id); a.audit("UPDATE","DOCUMENT_TYPE",id); return type(a.db.queryForMap("SELECT id,code,name,description,active FROM document_types WHERE id=?",id)); }
    @PreAuthorize("hasRole('ADMIN')") @Transactional public void deleteType(long id) { a.update("DELETE FROM document_types WHERE id=?",id); a.audit("DELETE","DOCUMENT_TYPE",id); }
    private DocumentView doc(Map<String,Object> r) { return new DocumentView(((Number)r.get("id")).longValue(),((Number)r.get("student_id")).longValue(),((Number)r.get("document_type_id")).longValue(),(String)r.get("type_name"),(String)r.get("status"),(String)r.get("purpose"),((java.sql.Timestamp)r.get("requested_at")).toLocalDateTime(),r.get("processed_at")==null?null:((java.sql.Timestamp)r.get("processed_at")).toLocalDateTime(),(String)r.get("admin_remarks"),r.get("issued_file_id")!=null); }
    private static final String DOC="SELECT d.id,d.student_id,d.document_type_id,t.name type_name,d.status,d.purpose,d.requested_at,d.processed_at,d.admin_remarks,d.issued_file_id FROM document_requests d JOIN document_types t ON t.id=d.document_type_id ";
    public List<DocumentView> docs(boolean admin) { String q=DOC+(admin?"ORDER BY d.requested_at DESC":"WHERE d.student_id=? ORDER BY d.requested_at DESC"); return (admin?a.db.queryForList(q):a.db.queryForList(q,a.student())).stream().map(this::doc).toList(); }
    public DocumentView doc(long id, boolean admin) { String q=DOC+"WHERE d.id=?"+(admin?"":" AND d.student_id=?"); List<Map<String,Object>> rows=admin?a.db.queryForList(q,id):a.db.queryForList(q,id,a.student()); if(rows.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Document request not found"); return doc(rows.getFirst()); }
    public DocumentView request(DocumentInput x) { long s=a.student(); if(a.db.queryForObject("SELECT COUNT(*) FROM document_types WHERE id=? AND active=TRUE",Integer.class,x.documentTypeId())==0) throw FinanceAccess.error(HttpStatus.BAD_REQUEST,"Document type unavailable"); long id=a.insert("INSERT INTO document_requests(student_id,document_type_id,purpose) VALUES(?,?,?)",s,x.documentTypeId(),x.purpose()); return doc(id,false); }
    @PreAuthorize("hasRole('ADMIN')") @Transactional public DocumentView doc(long id, boolean admin, DocumentReview x, MultipartFile file) { Map<String,Object> old=lockedDoc(id); String current=(String)old.get("status"), status=x.status().name(); if(!validTransition(current,status)) throw FinanceAccess.error(HttpStatus.CONFLICT,"Invalid document status transition"); if(status.equals("APPROVED") && file==null && old.get("issued_file_id")==null) throw FinanceAccess.error(HttpStatus.BAD_REQUEST,"Approved document requires a file"); Long fileId=old.get("issued_file_id")==null?null:((Number)old.get("issued_file_id")).longValue(); if(file!=null){ DocumentStorage.Stored f=files.store(file); fileId=a.insert("INSERT INTO uploaded_files(original_name,stored_name,content_type,size_bytes,sha256,uploaded_by) VALUES(?,?,?,?,?,?)",f.originalName(),f.storedName(),f.contentType(),f.size(),f.sha256(),a.user()); }
         a.update("UPDATE document_requests SET status=?,admin_remarks=?,processed_at=NOW(),processed_by=?,issued_file_id=? WHERE id=?",status,x.remarks(),a.user(),fileId,id); a.audit("REVIEW","DOCUMENT_REQUEST",id); return doc(id,true); }
    private static boolean validTransition(String from,String to) { return from.equals(to) || (from.equals("REQUESTED") && to.equals("PROCESSING")) || (from.equals("PROCESSING") && (to.equals("APPROVED") || to.equals("REJECTED"))); }
    @SuppressWarnings("unchecked") private Map<String,Object> lockedDoc(long id){ List<Map<String,Object>> r=a.db.queryForList("SELECT * FROM document_requests WHERE id=? FOR UPDATE",id); if(r.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Document request not found"); return r.getFirst(); }
    public Download download(long id) { Map<String,Object> r=lockedDoc(id); long student=a.student(); if(!Objects.equals(((Number)r.get("student_id")).longValue(),student)) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Document request not found"); if(!"APPROVED".equals(r.get("status")) || r.get("issued_file_id")==null) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Document not issued"); return fileDownload(((Number)r.get("issued_file_id")).longValue()); }
    private Download fileDownload(long fileId){ Map<String,Object> f=a.db.queryForMap("SELECT original_name,stored_name,content_type,size_bytes,sha256 FROM uploaded_files WHERE id=?",fileId); return new Download(files.read((String)f.get("stored_name"),((Number)f.get("size_bytes")).longValue(),(String)f.get("sha256")),(String)f.get("content_type"),(String)f.get("original_name")); }
    private FeeView fee(Map<String,Object> r){ BigDecimal total=(BigDecimal)r.get("total_amount"), paid=(BigDecimal)r.get("paid"); return new FeeView(((Number)r.get("id")).longValue(),((Number)r.get("student_id")).longValue(),((Number)r.get("semester_id")).longValue(),total,((java.sql.Date)r.get("due_date")).toLocalDate(),paid,total.subtract(paid).max(BigDecimal.ZERO)); }
    private static final String FEE="SELECT f.id,f.student_id,f.semester_id,f.total_amount,f.due_date,COALESCE(SUM(CASE WHEN p.status='VERIFIED' THEN p.amount ELSE 0 END),0) paid FROM fee_records f LEFT JOIN payments p ON p.fee_record_id=f.id ";
    public FeeSummary fees(Long semester){ String where="WHERE f.student_id=?"+(semester==null?"":" AND f.semester_id=?"); List<Map<String,Object>> rows=semester==null?a.db.queryForList(FEE+where+" GROUP BY f.id",a.student()):a.db.queryForList(FEE+where+" GROUP BY f.id",a.student(),semester); return summary(rows); }
    private FeeSummary summary(List<Map<String,Object>> rows){ List<FeeView> list=rows.stream().map(this::fee).toList(); return new FeeSummary(list,list.stream().map(FeeView::totalAmount).reduce(BigDecimal.ZERO,BigDecimal::add),list.stream().map(FeeView::verifiedPaid).reduce(BigDecimal.ZERO,BigDecimal::add),list.stream().map(FeeView::outstanding).reduce(BigDecimal.ZERO,BigDecimal::add)); }
    public FeeSummary allFees(){return summary(a.db.queryForList(FEE+"GROUP BY f.id"));}
    @Transactional public FeeView createFee(FeeInput x){
        if(a.db.queryForObject("SELECT COUNT(*) FROM students WHERE id=?",Integer.class,x.studentId())==0 || a.db.queryForObject("SELECT COUNT(*) FROM semesters WHERE id=?",Integer.class,x.semesterId())==0) throw FinanceAccess.error(HttpStatus.BAD_REQUEST,"Student or semester not found");
        long id=a.insert("INSERT INTO fee_records(student_id,semester_id,total_amount,due_date) VALUES(?,?,?,?)",x.studentId(),x.semesterId(),x.totalAmount(),x.dueDate()); a.audit("CREATE","FEE_RECORD",id); return allFees().fees().stream().filter(f->f.id()==id).findFirst().orElseThrow();
    }
    @Transactional public FeeView updateFee(long id, FeeInput x){
        List<Map<String,Object>> existing=a.db.queryForList("SELECT id FROM fee_records WHERE id=? FOR UPDATE",id); if(existing.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Fee record not found");
        if(a.db.queryForObject("SELECT COUNT(*) FROM students WHERE id=?",Integer.class,x.studentId())==0 || a.db.queryForObject("SELECT COUNT(*) FROM semesters WHERE id=?",Integer.class,x.semesterId())==0) throw FinanceAccess.error(HttpStatus.BAD_REQUEST,"Student or semester not found");
        if(x.totalAmount().compareTo(verified(id))<0) throw FinanceAccess.error(HttpStatus.CONFLICT,"Fee total cannot be below verified payments");
        a.update("UPDATE fee_records SET student_id=?,semester_id=?,total_amount=?,due_date=? WHERE id=?",x.studentId(),x.semesterId(),x.totalAmount(),x.dueDate(),id); a.audit("UPDATE","FEE_RECORD",id); return allFees().fees().stream().filter(f->f.id()==id).findFirst().orElseThrow();
    }
    @Transactional public void deleteFee(long id){a.update("DELETE FROM fee_records WHERE id=?",id); a.audit("DELETE","FEE_RECORD",id);}
    @Transactional public PaymentView submit(long feeId, PaymentInput x){ long s=a.student(); Map<String,Object> f=feeLock(feeId,s); BigDecimal outstanding=((BigDecimal)f.get("total_amount")).subtract(verified(feeId)); if(x.amount().compareTo(outstanding)>0) throw FinanceAccess.error(HttpStatus.CONFLICT,"Payment exceeds outstanding amount"); long id=a.insert("INSERT INTO payments(fee_record_id,amount,mode,transaction_reference,recorded_by) VALUES(?,?,?,?,?)",feeId,x.amount(),x.mode().name(),x.transactionReference(),a.user()); return payment(id); }
    private Map<String,Object> feeLock(long id,long s){ List<Map<String,Object>> rows=a.db.queryForList("SELECT * FROM fee_records WHERE id=? AND student_id=? FOR UPDATE",id,s); if(rows.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Fee record not found"); return rows.getFirst(); }
    private BigDecimal verified(long fee){ return a.db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM payments WHERE fee_record_id=? AND status='VERIFIED'",BigDecimal.class,fee); }
    private PaymentView payment(long id){ List<Map<String,Object>> r=a.db.queryForList("SELECT p.*,f.student_id FROM payments p JOIN fee_records f ON f.id=p.fee_record_id WHERE p.id=?",id); if(r.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Payment not found"); return pay(r.getFirst()); }
    private PaymentView pay(Map<String,Object> r){ return new PaymentView(((Number)r.get("id")).longValue(),((Number)r.get("fee_record_id")).longValue(),((Number)r.get("student_id")).longValue(),(BigDecimal)r.get("amount"),r.get("mode").toString(),r.get("transaction_reference").toString(),r.get("status").toString(),((java.sql.Timestamp)r.get("paid_at")).toLocalDateTime(),r.get("verified_at")==null?null:((java.sql.Timestamp)r.get("verified_at")).toLocalDateTime(),(String)r.get("receipt_no")); }
    public List<PaymentView> payments(boolean admin){ String q="SELECT p.*,f.student_id FROM payments p JOIN fee_records f ON f.id=p.fee_record_id "+(admin?"":"WHERE f.student_id=? ")+" ORDER BY p.paid_at DESC"; return (admin?a.db.queryForList(q):a.db.queryForList(q,a.student())).stream().map(this::pay).toList(); }
    @Transactional public PaymentView adminPayment(AdminPaymentInput x){ List<Map<String,Object>> locks=a.db.queryForList("SELECT * FROM fee_records WHERE id=? FOR UPDATE",x.feeRecordId()); if(locks.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Fee record not found"); Map<String,Object> f=locks.getFirst(); if(x.amount().compareTo(((BigDecimal)f.get("total_amount")).subtract(verified(x.feeRecordId())))>0) throw FinanceAccess.error(HttpStatus.CONFLICT,"Payment exceeds outstanding amount"); long id=a.insert("INSERT INTO payments(fee_record_id,amount,mode,transaction_reference,recorded_by) VALUES(?,?,?,?,?)",x.feeRecordId(),x.amount(),x.mode().name(),x.transactionReference(),a.user()); return payment(id); }
    @Transactional public PaymentView verify(long id, boolean accept){ List<Map<String,Object>> p=a.db.queryForList("SELECT p.*,f.total_amount,f.student_id FROM payments p JOIN fee_records f ON f.id=p.fee_record_id WHERE p.id=? FOR UPDATE",id); if(p.isEmpty()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Payment not found"); Map<String,Object> r=p.getFirst(); a.db.queryForList("SELECT id FROM fee_records WHERE id=? FOR UPDATE",((Number)r.get("fee_record_id")).longValue()); if(!"SUBMITTED".equals(r.get("status"))) throw FinanceAccess.error(HttpStatus.CONFLICT,"Payment already processed"); if(accept){ BigDecimal paid=verified(((Number)r.get("fee_record_id")).longValue()); if(paid.add((BigDecimal)r.get("amount")).compareTo((BigDecimal)r.get("total_amount"))>0) throw FinanceAccess.error(HttpStatus.CONFLICT,"Payment exceeds outstanding amount"); String receipt="R-"+UUID.randomUUID().toString().replace("-","").substring(0,16).toUpperCase(); a.update("UPDATE payments SET status='VERIFIED',verified_at=NOW(),verified_by=?,receipt_no=? WHERE id=?",a.user(),receipt,id); } else a.update("UPDATE payments SET status='REJECTED',verified_by=?,verified_at=NOW() WHERE id=?",a.user(),id); a.audit(accept?"VERIFY":"REJECT","PAYMENT",id); return payment(id); }
    public Download receipt(long id){ PaymentView p=payment(id); if(!"VERIFIED".equals(p.status()) || p.studentId()!=a.student()) throw FinanceAccess.error(HttpStatus.NOT_FOUND,"Receipt unavailable"); String html="<html><body><h1>Payment receipt</h1><p>Receipt: "+esc(p.receiptNo())+"</p><p>Reference: "+esc(p.transactionReference())+"</p><p>Amount: "+esc(p.amount().toPlainString())+"</p></body></html>"; return new Download(html.getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/html","receipt-"+p.receiptNo()+".html"); }
    private static String esc(String value) { return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;"); }
}
